import * as THREE from 'three';
import {createWorld} from './world.js';
import {circuits,circuitById} from './circuits.js';
import {Simulation,formatTime,clamp,angleDiff} from './simulation.js';
const $=s=>document.querySelector(s);
let world;
try{world=createWorld($("#world"));}catch(error){console.error(error);$('#error').hidden=false;$('#menu').hidden=true;throw error;}
let circuit=circuits[0],track,points,sim,bounds;const keys=new Set();let drsPressed=false,lightsShown=-1;let state='menu',cameraMode=0,audioEnabled=false,engine=null,last=performance.now(),accumulator=0,messageUntil=0,invalidShown=false,cameraInitialized=false,currentResult=null;
let records=[];let savedSettings={quality:'high',camera:1,circuit:'costa'};let storageOK=true;
// camera 0 chase, 1 driver's eyes (default), 2 T-cam. Records are stored per circuit.
try{const prefs=JSON.parse(localStorage.getItem('kyrvex.settings.v1')||'{}');savedSettings={quality:prefs.quality==='low'?'low':'high',camera:[0,1,2].includes(prefs.camera)?prefs.camera:1,circuit:circuitById(prefs.circuit).id};}catch{storageOK=false;}
const recordKey=id=>`kyrvex.records.${id}.v2`;
function loadRecords(id){try{let stored=localStorage.getItem(recordKey(id));if(stored===null&&id==='costa')stored=localStorage.getItem('kyrvex.records.v2');const raw=JSON.parse(stored||'[]');return Array.isArray(raw)?raw.filter(r=>Number.isFinite(r.time)&&r.time>0&&Array.isArray(r.sectors)&&r.sectors.length===3).sort((a,b)=>a.time-b.time).slice(0,10):[];}catch{storageOK=false;return [];}}
cameraMode=savedSettings.camera;world.quality(savedSettings.quality);
const best=()=>records[0]||null;
function saveSettings(){try{localStorage.setItem('kyrvex.settings.v1',JSON.stringify(savedSettings));}catch{storageOK=false;}}
function refreshBest(){$('#menu-best').textContent=formatTime(best()?.time);$('#hud-best').textContent=formatTime(best()?.time);}
$('#rpm').innerHTML=Array.from({length:15},(_,i)=>`<i class="${i>11?'red':''}"></i>`).join('');
function drawMap(canvas,current=false){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,pad=19,scale=Math.min((w-pad*2)/(bounds.maxX-bounds.minX),(h-pad*2)/(bounds.maxZ-bounds.minZ));const xy=p=>[(p.x-(bounds.minX+bounds.maxX)/2)*scale+w/2,(p.z-(bounds.minZ+bounds.maxZ)/2)*scale+h/2];ctx.clearRect(0,0,w,h);ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();points.forEach((p,i)=>{const [x,y]=xy(p);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.closePath();ctx.strokeStyle='#101d15';ctx.lineWidth=current?12:9;ctx.stroke();ctx.strokeStyle='#b1baa5';ctx.lineWidth=current?5:3;ctx.stroke();for(let sector=0;sector<3;sector++){const [x,y]=xy(points[sector*600]);ctx.fillStyle=['#d8ff3e','#87bca7','#a58abe'][sector];ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();}const [sx,sy]=xy(points[0]);ctx.fillStyle='#d8ff3e';ctx.font='9px Arial';ctx.fillText('S/F',sx+7,sy+2);if(current){const [x,y]=xy(sim);ctx.shadowBlur=10;ctx.shadowColor='#d8ff3e';ctx.fillStyle='#d8ff3e';ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#1c2b0f';ctx.lineWidth=2;ctx.stroke();}}
// Load a circuit into the world, physics, menu card and HUD.
function selectCircuit(id){circuit=circuitById(id);track=world.loadCircuit(circuit);points=track.points;sim=new Simulation(points,track);lightsShown=-1;records=loadRecords(circuit.id);
 bounds={minX:Math.min(...points.map(p=>p.x)),maxX:Math.max(...points.map(p=>p.x)),minZ:Math.min(...points.map(p=>p.z)),maxZ:Math.max(...points.map(p=>p.z))};
 const i=circuits.indexOf(circuit),pad=n=>String(n).padStart(2,'0');$('#track-index').textContent=`${pad(i+1)} / ${pad(circuits.length)}`;$('#track-location').textContent=circuit.location;$('#track-name').textContent=circuit.name;$('#track-title').textContent=circuit.title;$('#track-length').textContent=(track.length/1000).toFixed(2);$('#track-corners').textContent=String(track.corners.length);
 const [icon,temp,cond]=circuit.weather;$('#track-weather').innerHTML=`${icon} <b>${temp}</b><span>${cond}</span>`;$('#hud-circuit').textContent=circuit.short;$('#map-name').textContent=circuit.name;$('#track-preview').setAttribute('aria-label',`${circuit.name} 서킷 지도`);
 drawMap($('#track-preview'));refreshBest();savedSettings.circuit=circuit.id;saveSettings();}
