function openModal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();if(state==='paused')resume();}
$('#close-modal').onclick=closeModal;
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
function showHelp(){openModal(`<div class="eyebrow">DRIVER BRIEFING</div><h2>완벽한 랩을 위한 준비.</h2><div class="control-grid"><div><kbd>W / ↑</kbd> 가속</div><div><kbd>S / ↓</kbd> 브레이크</div><div><kbd>A D / ← →</kbd> 조향</div><div><kbd>C</kbd> 드라이버 / T캠 / 추적 시점</div><div><kbd>E / SPACE</kbd> DRS 열기</div><div><kbd>R</kbd> 트랙 복귀 · 랩 무효</div><div><kbd>ESC</kbd> 일시정지</div></div><div class="rules"><b>F1 예선 기반 타임어택</b><ul><li>준비 구간을 달려 출발선을 통과하면 계측이 시작됩니다.</li><li>3개 섹터를 순서대로 통과해 한 랩을 완주하세요. 가장 빠른 유효 랩이 개인 기록입니다.</li><li>네 바퀴가 모두 흰 경계선 밖으로 나가면 현재 랩은 무효입니다. 마지막 구간 이탈은 다음 랩도 무효 처리합니다.</li><li>자동 8단 변속. 코너 진입 전에 감속하고 탈출할 때 가속하세요. 150·100·50 브레이킹 보드를 기준으로 삼으세요.</li><li>DRS 구간(긴 직선)에서 E 또는 스페이스로 리어 윙을 열면 최고 속도가 오릅니다. 브레이크를 밟거나 구간을 벗어나면 닫힙니다.</li><li>상대 차량 없이 무제한 주행합니다. 기록은 이 브라우저에 저장되며, 온라인 순위표는 포함되지 않습니다.</li></ul><a href="https://www.formula1.com/en/latest/article/f1-glossary-p-t.GBhLQtpeu9b8LrK5VM0F1" target="_blank" rel="noopener noreferrer">Formula 1 · 섹터와 트랙 리밋 안내 ↗</a><p>가상 서킷과 단순화한 주행 모델을 사용합니다. 공식 F1 게임이나 전체 경기 규정의 시뮬레이터는 아닙니다.</p></div>`);}
$('#how').onclick=showHelp;$('#nav-drive').onclick=()=>$('#start').focus();
$('#records').onclick=()=>{openModal(`<div class="eyebrow">LOCAL RECORDS / ${circuit.short}</div><h2>천분의 일 초의 차이.</h2><p>이 브라우저의 유효 랩 TOP 10</p>${records.length?records.map((r,i)=>`<div class="record-row"><span>${String(i+1).padStart(2,'0')}</span><strong>${formatTime(r.time)}</strong><small>${new Date(Number(r.date)||0).toLocaleDateString('ko-KR')}</small></div>`).join(''):'<p class="empty-records">아직 기록이 없습니다.<br>첫 번째 유효 랩을 완주해 기준을 세워보세요.</p>'}${!storageOK?'<p>브라우저 저장 공간에 접근할 수 없어 이번 세션에서만 기록됩니다.</p>':''}`);};
$('#settings').onclick=()=>{openModal(`<div class="eyebrow">SETUP</div><h2>드라이빙 환경</h2><label class="settings-row">그래픽 품질<select id="quality"><option value="high">높음 · 실시간 그림자</option><option value="low">성능 우선</option></select></label><label class="settings-row">기본 카메라<select id="camera-setting"><option value="1">드라이버 시점 · 1인칭</option><option value="2">T캠 · 온보드 중계</option><option value="0">추적 시점 · 3인칭</option></select></label><label class="settings-row">엔진 사운드<select id="audio-setting"><option value="off">끄기</option><option value="on">켜기</option></select></label><p>키보드와 터치 조작을 지원합니다.<br>원활한 주행을 위해 데스크톱 전체 화면을 권장합니다.</p>`);$('#quality').value=savedSettings.quality;$('#camera-setting').value=String(cameraMode);$('#audio-setting').value=audioEnabled?'on':'off';$('#quality').onchange=e=>{savedSettings.quality=e.target.value;world.quality(savedSettings.quality);saveSettings();};$('#camera-setting').onchange=e=>{cameraMode=Number(e.target.value);savedSettings.camera=cameraMode;saveSettings();};$('#audio-setting').onchange=e=>setSound(e.target.value==='on');};
function notify(text,warning=false,duration=3.5){$('#race-message').textContent=text;$('#race-message').className='visible'+(warning?' warning':'');messageUntil=performance.now()+duration*1000;}
function setSound(enabled){audioEnabled=enabled;if(enabled&&!engine){try{const context=new AudioContext(),gain=context.createGain(),filter=context.createBiquadFilter(),osc=context.createOscillator(),second=context.createOscillator();gain.gain.value=0;filter.type='lowpass';filter.frequency.value=1700;osc.type='sawtooth';second.type='triangle';osc.connect(filter);second.connect(filter);filter.connect(gain);gain.connect(context.destination);osc.start();second.start();engine={context,gain,osc,second,filter};}catch{audioEnabled=false;}}if(engine)engine.context.resume().catch(()=>{});$('#sound').innerHTML=`♫ <span>${audioEnabled?'ON':'OFF'}</span>`;$('#sound').setAttribute('aria-label',`엔진 사운드 ${audioEnabled?'끄기':'켜기'}`);}
$('#sound').onclick=()=>setSound(!audioEnabled);
function start(){sim.reset();keys.clear();state='racing';invalidShown=false;cameraInitialized=false;accumulator=0;currentResult=null;$('#menu').hidden=true;$('#hud').hidden=false;document.body.classList.add('racing');$('#modal').close();world.studio.visible=false;world.menuLight.visible=false;world.fill.intensity=.8;notify('준비 구간 · 가속해 출발선을 통과하세요',false,6);if(audioEnabled)setSound(true);}
$('#start').onclick=start;
function pause(){if(state!=='racing')return;state='paused';keys.clear();openModal(`<div class="eyebrow">SESSION PAUSED</div><h2>잠시, 숨 고르기.</h2><p>현재 랩 ${formatTime(sim.timer.elapsed)} · ${sim.timer.invalid?'무효 랩':'유효 랩'}</p><div class="modal-actions"><button class="primary" id="resume">계속 주행 ↗</button><button id="restart">새 세션 시작</button><button id="exit">시작 화면으로</button></div>`);$('#resume').onclick=resume;$('#restart').onclick=start;$('#exit').onclick=goMenu;}
function resume(){state='racing';last=performance.now();accumulator=0;$('#modal').close();}
function goMenu(){state='menu';keys.clear();$('#modal').close();$('#menu').hidden=false;$('#hud').hidden=true;document.body.classList.remove('racing');world.studio.visible=true;world.menuLight.visible=true;world.fill.intensity=2;refreshBest();}
$('#pause').onclick=pause;
addEventListener('keydown',e=>{if(e.target.matches?.('select,input,textarea'))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.repeat)return;if(state==='menu'&&!$('#modal').open&&(e.code==='ArrowLeft'||e.code==='ArrowRight')){cycleCircuit(e.code==='ArrowLeft'?-1:1);return;}if(e.code==='Escape'){if(state==='racing'){pause();e.preventDefault();}else if(state==='paused'){resume();e.preventDefault();}return;}if(state!=='racing')return;keys.add(e.code);if(e.code==='KeyE'||e.code==='Space')drsPressed=true;if(e.code==='KeyC'){cameraMode=({1:2,2:0,0:1})[cameraMode];cameraInitialized=false;notify(['추적 시점','드라이버 시점','T캠'][cameraMode],false,1.5);}if(e.code==='KeyR'){sim.recover();cameraInitialized=false;invalidShown=true;notify('트랙 복귀 · 현재 랩 무효',true);}});
addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{keys.clear();pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});
for(const button of document.querySelectorAll('[data-key]')){button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);keys.add(button.dataset.key);if(button.dataset.key==='KeyE')drsPressed=true;});for(const event of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(event,()=>keys.delete(button.dataset.key));}
function onLap(result){const previousBest=best()?.time??Infinity;currentResult=result;if(result.valid){records.push({...result,date:Date.now()});records.sort((a,b)=>a.time-b.time);records=records.slice(0,10);try{localStorage.setItem(recordKey(circuit.id),JSON.stringify(records));}catch{storageOK=false;}refreshBest();notify(`${result.time<previousBest?'PERSONAL BEST':'LAP COMPLETE'}  ${formatTime(result.time)}${!storageOK?' · 세션 내 저장':''}`,false,6);}else{notify(`무효 랩  ${formatTime(result.time)} · 다음 랩에 도전하세요`,true,5);}}
const gearOf=kmh=>kmh<1?'N':Math.min(8,Math.floor(kmh/42)+1),rpmOf=kmh=>kmh<1?0:Math.min(15,5+(kmh%42)/42*10);
function updateHud(){const timer=sim.timer,speed=sim.speed*3.6,gear=gearOf(speed);$('#speed').textContent=String(Math.round(speed));$('#gear').textContent=String(gear);$('#lap-time').textContent=formatTime(timer.elapsed);$('#lap-time').style.color=timer.invalid?'#ff8d73':'';$('#lap-label').textContent=timer.active?`LAP ${String(timer.lap).padStart(2,'0')} · ${timer.invalid?'INVALID':'FLYING LAP'}`:'OUT LAP · 준비 구간';$('#progress').textContent=Math.floor(sim.location.progress*100);$('#drs').className=sim.drs?'open':sim.drsZone?'available':'';$('#throttle-bar').style.width=`${sim.throttle*62}px`;$('#brake-bar').style.width=`${sim.brake*62}px`;
 const rpm=rpmOf(speed);[...$('#rpm').children].forEach((el,i)=>el.classList.toggle('on',i<rpm));for(let i=0;i<3;i++){const el=$(`#s${i+1}`),value=timer.sectors[i];el.textContent=`S${i+1} ${Number.isFinite(value)?value.toFixed(3):'—'}`;el.style.borderColor=Number.isFinite(value)?(best()&&value<best().sectors[i]?'#bc80ed':'#d8ff3e'):'';}
 let delta=null;const benchmark=best();if(timer.active&&benchmark?.samples?.length){let closest=null;for(const sample of benchmark.samples){if(sample[0]>sim.location.progress)break;closest=sample;}if(closest&&sim.location.progress-closest[0]<.015)delta=timer.elapsed-closest[1];}$('#delta').textContent=delta===null?'—':`${delta<=0?'−':'+'}${Math.abs(delta).toFixed(3)}`;$('#delta').style.color=delta===null?'':delta<=0?'#d8ff3e':'#ff997f';drawMap($('#minimap'),true);
}
const targetPosition=new THREE.Vector3(),targetLook=new THREE.Vector3();let wheelRotation=0,hudElapsed=0;
const eye=new THREE.Vector3(),headTilt=new THREE.Quaternion(),headEuler=new THREE.Euler(0,0,0,'YXZ');let lastHeading=0,lastSpeed=0,headLat=0,headLon=0;
const tcam=new THREE.Vector3(0,1.5,.58),tcamTilt=new THREE.Quaternion().setFromEuler(new THREE.Euler(-.13,0,0));
